<?php
require 'config.php'; require_login();
$id=max(0,(int)($_GET['run_id']??0));
$st=$pdo->prepare('SELECT r.*,s.name,s.start_url,s.allowed_domains FROM scan_runs r JOIN sites s ON s.id=r.site_id WHERE r.id=?');$st->execute([$id]);$run=$st->fetch();if(!$run){http_response_code(404);exit('Không tìm thấy phiên quét.');}
$st=$pdo->prepare("SELECT f.*,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(l.source_url,' (dòng ',l.line_number,')') SEPARATOR ' | '),'') source_pages,COALESCE(GROUP_CONCAT(DISTINCT l.tag_snippet SEPARATOR ' | '),'') source_html FROM findings f LEFT JOIN links l ON l.run_id=f.run_id AND l.normalized_url=f.base_target_url WHERE f.run_id=? GROUP BY f.id ORDER BY CASE f.status_category WHEN 'http_error' THEN 1 WHEN 'missing_anchor' THEN 2 WHEN 'connection_error' THEN 3 WHEN 'unknown' THEN 4 WHEN 'unchecked' THEN 5 ELSE 6 END,f.id");$st->execute([$id]);$rows=$st->fetchAll();
$counts=[];foreach($rows as $r)$counts[$r['status_category']]=($counts[$r['status_category']]??0)+1;
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Báo cáo LinkScope #<?=e($id)?></title><style>
