</style></head><body><main class="page"><header class="top"><div><div class="brand">↗ LinkScope</div><h1 style="font-size:22px;margin:10px 0 5px">Báo cáo kiểm tra liên kết</h1><div class="muted">Phiên #<?=e($run['id'])?> · <?=e($run['name'])?></div></div><div class="meta"><div><strong>URL bắt đầu:</strong> <?=e($run['start_url'])?></div><div><strong>Thời điểm:</strong> <?=e($run['started_at'])?></div><div><strong>Trạng thái:</strong> <?=e($run['status'])?></div><div><strong>Phạm vi:</strong> <?=e($run['allowed_domains'])?></div></div></header>
<div class="actions"><button class="btn" onclick="window.print()">In / Lưu thành PDF</button><a class="btn secondary" href="report.php?run_id=<?=(int)$id?>">Quay lại báo cáo</a></div>
<section class="stats"><div class="stat">Trang đã quét<strong><?=number_format((int)$run['total_pages_crawled'])?></strong></div><div class="stat">Liên kết tìm thấy<strong><?=number_format((int)$run['total_links_found'])?></strong></div><div class="stat">Lỗi ghi nhận<strong><?=number_format((int)$run['total_errors'])?></strong></div><div class="stat">Chưa xác định / bỏ qua<strong><?=number_format((int)$run['total_unchecked'])?></strong></div></section>
<div class="chips"><?php foreach($counts as $status=>$count):?><span class="chip"><?=e($status)?>: <strong><?=$count?></strong></span><?php endforeach;?></div>
<h2>Chi tiết phát hiện (<?=count($rows)?>)</h2><div class="table-wrap"><table><thead><tr><th style="width:20%">URL đích</th><th style="width:8%">Loại</th><th style="width:7%">HTTP</th><th style="width:10%">Trạng thái</th><th style="width:20%">Trang nguồn / dòng</th><th style="width:17%">Thẻ HTML nguồn</th><th style="width:18%">Chi tiết</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">Không có phát hiện nào được lưu cho phiên này.</td></tr><?php endif;foreach($rows as $r):?><tr><td class="url"><?=e($r['normalized_url'])?><?=($r['fragment']??'')!==''?'<div class="source">#'.e($r['fragment']).'</div>':''?></td><td><?=e($r['resource_type'])?></td><td><?=e($r['http_status']??'—')?></td><td class="<?=in_array($r['status_category'],['http_error','connection_error','missing_anchor'],true)?'error':($r['status_category']==='ok'?'ok':'')?>"><?=e($r['status_category'])?></td><td class="source"><?=e($r['source_pages']?:'—')?></td><td class="source"><?=e($r['source_html']?:'—')?></td><td><?=e($r['error_detail'])?><?php if($r['redirect_chain']):?><div class="source">Redirect: <?=e($r['redirect_chain'])?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p class="muted" style="margin-top:20px">Tạo bởi LinkScope · PHP thuần / MySQL · Báo cáo chỉ phản ánh kết quả tại thời điểm quét.</p></main></body></html>
